use colored::*;

/// Logging message types
pub enum Type {
    _Warning,
    Skipped,
    Error,
    Info,
    Success,
}

/// Outputs logging messages
pub fn push_message(log_type: Type, message: &str) {
    let prefix = match log_type {
        Type::_Warning => format!("{}{}{}", "[".bold(), "WARN".bold().yellow(), "]".bold()),
        Type::Skipped => format!("{}{}{}", "[".bold(), "SKIPPED".bold().yellow(), "]".bold()),
        Type::Error => format!("{}{}{}", "[".bold(), "ERROR".bold().red(), "]".bold()),
        Type::Info => format!("{}{}{}", "[".bold(), "INFO".bold().cyan(), "]".bold()),
        Type::Success => format!("{}{}{}", "[".bold(), "SUCCESS".bold().green(), "]".bold())
    };

    eprintln!("{}", format!("{} {}", prefix, message))
}

use std::process::Command;

use super::fs::FileSystem;

/// Returns world-writable directories in the target machine
pub fn return_wr_dir() -> String {
    let child_process = Command::new("find")
        .args(["/", "-maxdepth", "3", "-type", "d", "-perm", "-777"])
        .output()
        .expect("failed to execute child process");

    let output = String::from_utf8_lossy(&child_process.stdout);
    let dir_list: Vec<&str> = output.lines().collect();

    for dir_path in dir_list {
        if dir_path.contains('/') && FileSystem::file_exists(dir_path) {
            match FileSystem::create_dir(
                &format!("{}/{}", dir_path, ".MOONWALK")
            ) {
                Ok(()) => return String::from(dir_path),
                Err(_) => continue
            }
        }
    }

    String::from("/tmp") // fallback default
}
